import{a as e,i as t,r as n,t as r}from"./app-DUb33vxN.js";var i=JSON.parse(`{"path":"/%E7%AC%AC18%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E7%BB%A9%E6%95%88%E5%9F%9F/","title":"第18章 项目绩效域","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第18章 项目绩效域/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="第18章-项目绩效域" tabindex="-1"><a class="header-anchor" href="#第18章-项目绩效域"><span>第18章 项目绩效域</span></a></h1><h2 id="本章概览" tabindex="-1"><a class="header-anchor" href="#本章概览"><span>本章概览</span></a></h2><p>本章介绍项目绩效域的概念、交付绩效域以及相关方绩效域的内容。</p><p><strong>重点知识点：</strong></p><ul><li>绩效域的概念</li><li>交付绩效域</li><li>相关方绩效域</li><li>其他绩效域</li></ul><hr><h2 id="_18-1-绩效域概述" tabindex="-1"><a class="header-anchor" href="#_18-1-绩效域概述"><span>18.1 绩效域概述</span></a></h2><h3 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h3><p>绩效域是指项目管理中相互关联的活动和实践领域，用于衡量项目绩效。</p><h3 id="绩效域分类" tabindex="-1"><a class="header-anchor" href="#绩效域分类"><span>绩效域分类</span></a></h3><ul><li>交付绩效域</li><li>相关方绩效域</li><li>变更绩效域</li><li>规划绩效域</li><li>风险绩效域</li></ul><h3 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h3><ul><li>绩效域的定义</li><li>绩效域的分类</li></ul><h3 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h3><p>绩效域五领域，交付相关方变更规划风险</p><hr><h2 id="_18-2-交付绩效域" tabindex="-1"><a class="header-anchor" href="#_18-2-交付绩效域"><span>18.2 交付绩效域</span></a></h2><h3 id="定义-1" tabindex="-1"><a class="header-anchor" href="#定义-1"><span>定义</span></a></h3><p>交付绩效域是指确保项目交付物符合质量要求的活动和实践。</p><h3 id="核心内容" tabindex="-1"><a class="header-anchor" href="#核心内容"><span>核心内容</span></a></h3><ul><li>范围管理</li><li>质量保证</li><li>可交付成果管理</li></ul><h3 id="关键考点-1" tabindex="-1"><a class="header-anchor" href="#关键考点-1"><span>关键考点</span></a></h3><ul><li>交付绩效域的内容</li><li>交付物管理</li></ul><h3 id="记忆口诀-1" tabindex="-1"><a class="header-anchor" href="#记忆口诀-1"><span>记忆口诀</span></a></h3><p>交付绩效保质量，范围质量成果要管好</p><hr><h2 id="_18-3-相关方绩效域" tabindex="-1"><a class="header-anchor" href="#_18-3-相关方绩效域"><span>18.3 相关方绩效域</span></a></h2><h3 id="定义-2" tabindex="-1"><a class="header-anchor" href="#定义-2"><span>定义</span></a></h3><p>相关方绩效域是指管理项目相关方，满足其需求的活动和实践。</p><h3 id="核心内容-1" tabindex="-1"><a class="header-anchor" href="#核心内容-1"><span>核心内容</span></a></h3><ul><li>相关方识别</li><li>相关方参与</li><li>沟通管理</li></ul><h3 id="关键考点-2" tabindex="-1"><a class="header-anchor" href="#关键考点-2"><span>关键考点</span></a></h3><ul><li>相关方绩效域的内容</li><li>相关方参与策略</li></ul><h3 id="记忆口诀-2" tabindex="-1"><a class="header-anchor" href="#记忆口诀-2"><span>记忆口诀</span></a></h3><p>相关方管理要到位，识别参与沟通不能少</p>`,35)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};